#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=9
cd "$(dirname "$0")/.."   # repo root, so .env lands next to app.py
PY=$(command -v python || command -v python3)

banner "Musical Memories: deploy to Render + Neon"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Spotify: app keys"
say "Your existing Spotify app powers song search for everyone (guests included)."
open_url "https://developer.spotify.com/dashboard"
step "Open your Musical Memories app, then click Settings."
step "Copy the Client ID."
ask SPOTIFY_CLIENT_ID "Paste the Client ID:"
step "Click 'View client secret' and copy it."
ask_secret SPOTIFY_CLIENT_SECRET "Paste the Client secret:"
write_env SPOTIFY_CLIENT_ID "$SPOTIFY_CLIENT_ID"
write_env SPOTIFY_CLIENT_SECRET "$SPOTIFY_CLIENT_SECRET"
# local dev callback; Spotify rejects http://localhost, only 127.0.0.1 works
write_env SPOTIFY_REDIRECT_URI "http://127.0.0.1:5000/callback"
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Spotify: check guest search works"
say "Asking Spotify for an app-only token and searching for one song..."
if SPOTIFY_CLIENT_ID="$SPOTIFY_CLIENT_ID" SPOTIFY_CLIENT_SECRET="$SPOTIFY_CLIENT_SECRET" "$PY" -c '
import os, requests, sys
r = requests.post("https://accounts.spotify.com/api/token",
    auth=(os.environ["SPOTIFY_CLIENT_ID"], os.environ["SPOTIFY_CLIENT_SECRET"]),
    data={"grant_type": "client_credentials"})
if not r.ok: sys.exit(f"token request failed: {r.status_code} {r.text[:200]}")
s = requests.get("https://api.spotify.com/v1/search", params={"q": "africa toto", "type": "track", "limit": 1},
    headers={"Authorization": "Bearer " + r.json()["access_token"]})
items = s.json().get("tracks", {}).get("items", []) if s.ok else []
if not items: sys.exit(f"search failed: {s.status_code} {s.text[:200]}")
print("  found:", items[0]["name"], "-", items[0]["artists"][0]["name"])
'; then
  say "Guest search will work."
  pause
else
  warn "Spotify blocked app-only search for this app. Guests won't be able to search."
  confirm "Continue the deploy anyway?" || exit 1
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Mapbox: access token"
say "Mapbox draws the location picker and the map page."
open_url "https://account.mapbox.com/access-tokens/"
step "Copy the 'Default public token' (starts with pk.)."
ask MAPBOX_ACCESS_TOKEN "Paste the token:"
write_env MAPBOX_ACCESS_TOKEN "$MAPBOX_ACCESS_TOKEN"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Gemini: song recommendations"
say "Gemini suggests songs on each note page. Without a key, 3 fixed songs are shown."
if confirm "Use a Gemini API key?"; then
  open_url "https://aistudio.google.com/apikey"
  step "Click 'Create API key' (or copy an existing one)."
  ask_secret GEMINI_API_KEY "Paste the API key:"
  write_env GEMINI_API_KEY "$GEMINI_API_KEY"
  write_env SKIP_GEMINI "false"
else
  GEMINI_API_KEY=""
  write_env SKIP_GEMINI "true"
fi
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Neon: free Postgres database"
say "Render's disk is wiped on restart, so the database lives on Neon instead."
open_url "https://console.neon.tech"
step "Create a new project (any name, nearest region)."
step "On the project dashboard, click 'Connect' and copy the connection string."
note "It looks like postgresql://user:pass@ep-....neon.tech/neondb?sslmode=require"
ask_secret DATABASE_URL "Paste the connection string:"
note "Not saved to .env, so local dev keeps using its own SQLite file."
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub: push the code"
say "Render deploys whatever is on GitHub, so the guest-mode changes must be pushed."
if [[ -n "$(git status --porcelain)" ]]; then
  warn "You have uncommitted changes:"
  git status --short | sed 's/^/    /'
  say "Commit and push them in another terminal, then come back."
else
  git fetch -q origin 2>/dev/null || true
  ahead=$(git rev-list --count '@{u}..HEAD' 2>/dev/null || echo "?")
  [[ "$ahead" == "0" ]] && say "Everything is pushed." || warn "$ahead local commit(s) not pushed yet. Run: git push"
fi
pause "Press Enter once your changes are on GitHub"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Render: create the web service"
ask RENDER_NAME "Service name you'll use on Render (e.g. musical-memories):"
RENDER_URL="https://${RENDER_NAME}.onrender.com"
SECRET_KEY=$("$PY" -c 'import secrets; print(secrets.token_hex(32))')
open_url "https://dashboard.render.com/web/new"
step "Connect GitHub and pick the Musical-Memories repo."
step "Name: ${BOLD}${RENDER_NAME}${RESET}   Language: Python 3   Branch: master"
step "Build Command: ${BOLD}pip install -r requirements.txt${RESET}"
step "Start Command: ${BOLD}gunicorn app:app${RESET}"
step "Instance Type: Free"
step "Under Environment Variables, click 'Add from .env' and paste this block:"
warn "This block contains secrets. Clear your terminal after pasting."
printf '\n'
printf '%s\n' \
  "DATABASE_URL=$DATABASE_URL" \
  "SECRET_KEY=$SECRET_KEY" \
  "SPOTIFY_CLIENT_ID=$SPOTIFY_CLIENT_ID" \
  "SPOTIFY_CLIENT_SECRET=$SPOTIFY_CLIENT_SECRET" \
  "SPOTIFY_REDIRECT_URI=$RENDER_URL/callback" \
  "MAPBOX_ACCESS_TOKEN=$MAPBOX_ACCESS_TOKEN" \
  "SKIP_GEMINI=$SKIP_GEMINI" | sed 's/^/    /'
[[ -n "$GEMINI_API_KEY" ]] && printf '    GEMINI_API_KEY=%s\n' "$GEMINI_API_KEY"
printf '\n'
step "Click 'Deploy Web Service' and wait for the log to say it's live."
note "If Render gave a different URL than $RENDER_URL, update SPOTIFY_REDIRECT_URI to match."
pause "Press Enter once the deploy is live"
LIVE_URL=""
ask LIVE_URL "Live URL shown at the top of the Render page (Enter for $RENDER_URL):" || true
RENDER_URL="${LIVE_URL:-$RENDER_URL}"
RENDER_URL="${RENDER_URL%/}"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Spotify: allow the new callback"
say "Only needed for your 5 allowlisted Spotify logins; guests don't use it."
open_url "https://developer.spotify.com/dashboard"
step "Open the app → Settings → Edit."
step "Under Redirect URIs, add ${BOLD}$RENDER_URL/callback${RESET}, then Save."
note "Keep http://127.0.0.1:5000/callback there too for local dev."
pause

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Check the live site"
say "Fetching $RENDER_URL (a free instance can take ~1 minute to wake up)..."
if curl -fsSL --max-time 120 "$RENDER_URL" | grep -q "Try as guest"; then
  say "${GREEN}✓${RESET} The home page is up and shows 'Try as guest'."
  open_url "$RENDER_URL"
else
  warn "Couldn't see the guest button. Check the Logs tab on Render."
  SKIPPED+=("Live check failed for $RENDER_URL. See the Render logs")
fi
pause

finish
}

run_wizard "$@"; exit
